public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;
    int[][] dp = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) {
                continue;
            }

            // Check horizontal
            if (j > 0 && mat[i][j - 1] == 1) {
                dp[i][j] = dp[i][j - 1] + 1;
            } else {
                dp[i][j] = 1;
            }

            // Check vertical
            if (i > 0 && mat[i - 1][j] == 1) {
                dp[i][j] = max(dp[i][j], dp[i - 1][j] + 1);
            }

            // Check diagonal
            if (i > 0 && j > 0 && mat[i - 1][j - 1] == 1) {
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 1] + 1);
            }

            // Check anti-diagonal
            if (i > 0 && j < n - 1 && mat[i - 1][j + 1] == 1) {
                dp[i][j] = max(dp[i][j], dp[i - 1][j + 1] + 1);
            }

            maxLength = max(maxLength, dp[i][j]);
        }
    }

    return maxLength;
}

